-- Sauti Yetu / NCCeAS initial PostgreSQL schema
-- Migration: 0001_initial_schema.sql
-- Requires PostgreSQL 15+. Apply only to a new development database after review.
-- Password/passphrase hashes are generated by the application with Argon2id.
-- Guardian phone numbers and consent documents must be encrypted by the application
-- before persistence; this schema intentionally has no plaintext credential columns.

BEGIN;

CREATE TYPE account_role AS ENUM (
  'public_child', 'delegate', 'speaker', 'clerk',
  'coordinator', 'stakeholder', 'admin'
);
CREATE TYPE account_status AS ENUM ('pending', 'active', 'suspended', 'archived');
CREATE TYPE consent_status AS ENUM ('pending', 'approved', 'rejected', 'withdrawn');
CREATE TYPE sitting_status AS ENUM ('draft', 'published', 'in_progress', 'concluded', 'cancelled');
CREATE TYPE motion_status AS ENUM ('draft', 'submitted', 'under_debate', 'committee_review', 'adopted', 'rejected', 'withdrawn');
CREATE TYPE debate_request_status AS ENUM ('pending', 'approved', 'rejected', 'completed', 'cancelled');
CREATE TYPE vote_choice AS ENUM ('yes', 'no', 'abstain');
CREATE TYPE concern_status AS ENUM ('submitted', 'under_review', 'consolidated', 'escalated', 'responded', 'closed', 'referred_to_safeguarding');
CREATE TYPE resolution_status AS ENUM ('draft', 'approved', 'sent', 'acknowledged', 'action_in_progress', 'completed', 'closed');
CREATE TYPE stakeholder_update_status AS ENUM ('received', 'in_progress', 'done');

CREATE TABLE users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  full_name TEXT NOT NULL CHECK (length(trim(full_name)) BETWEEN 2 AND 160),
  role account_role NOT NULL DEFAULT 'public_child',
  status account_status NOT NULL DEFAULT 'pending',
  age SMALLINT CHECK (age IS NULL OR age BETWEEN 5 AND 120),
  gender TEXT CHECK (gender IS NULL OR length(gender) <= 40),
  school TEXT CHECK (school IS NULL OR length(school) <= 200),
  county TEXT CHECK (county IS NULL OR length(county) <= 100),
  sub_county TEXT CHECK (sub_county IS NULL OR length(sub_county) <= 100),
  ward TEXT CHECK (ward IS NULL OR length(ward) <= 100),
  -- HMAC-SHA-256 of a normalised guardian phone, generated with a server-side
  -- pepper. It supports lookup without storing the phone in plaintext.
  guardian_phone_lookup_hash BYTEA UNIQUE,
  guardian_phone_ciphertext BYTEA,
  -- Adults use a normalised work email; child accounts use guardian phone lookup.
  email_normalized TEXT UNIQUE,
  password_hash TEXT,
  passphrase_hash TEXT,
  organisation TEXT CHECK (organisation IS NULL OR length(organisation) <= 200),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_login_at TIMESTAMPTZ,
  CHECK (
    (role IN ('public_child', 'delegate') AND guardian_phone_lookup_hash IS NOT NULL)
    OR role NOT IN ('public_child', 'delegate')
  ),
  CHECK (
    (role IN ('public_child', 'delegate') AND passphrase_hash IS NOT NULL AND password_hash IS NULL)
    OR (role NOT IN ('public_child', 'delegate') AND password_hash IS NOT NULL AND passphrase_hash IS NULL)
    OR status = 'pending'
  )
);

CREATE INDEX users_role_status_idx ON users(role, status);
CREATE INDEX users_location_idx ON users(county, sub_county, ward);

CREATE TABLE guardian_consents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  child_user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  guardian_name TEXT NOT NULL CHECK (length(trim(guardian_name)) BETWEEN 2 AND 160),
  guardian_phone_lookup_hash BYTEA NOT NULL,
  consent_document_storage_key TEXT,
  consent_text_version TEXT NOT NULL,
  status consent_status NOT NULL DEFAULT 'pending',
  reviewed_by UUID REFERENCES users(id) ON DELETE RESTRICT,
  reviewed_at TIMESTAMPTZ,
  granted_at TIMESTAMPTZ,
  withdrawn_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK ((status <> 'approved') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND granted_at IS NOT NULL))
);
CREATE INDEX guardian_consents_child_status_idx ON guardian_consents(child_user_id, status);

CREATE TABLE sittings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 3 AND 240),
  session_number INTEGER CHECK (session_number IS NULL OR session_number > 0),
  scheduled_at TIMESTAMPTZ NOT NULL,
  venue TEXT,
  order_paper_storage_key TEXT,
  status sitting_status NOT NULL DEFAULT 'draft',
  created_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  published_at TIMESTAMPTZ,
  concluded_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX sittings_schedule_idx ON sittings(scheduled_at DESC);

CREATE TABLE sitting_attendance (
  sitting_id UUID NOT NULL REFERENCES sittings(id) ON DELETE RESTRICT,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  left_at TIMESTAMPTZ,
  attendance_source TEXT NOT NULL DEFAULT 'application',
  PRIMARY KEY (sitting_id, user_id)
);

CREATE TABLE motions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  sitting_id UUID NOT NULL REFERENCES sittings(id) ON DELETE RESTRICT,
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 5 AND 240),
  description TEXT NOT NULL CHECK (length(trim(description)) BETWEEN 10 AND 12000),
  proposed_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  status motion_status NOT NULL DEFAULT 'draft',
  committee TEXT,
  submitted_at TIMESTAMPTZ,
  closed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX motions_sitting_status_idx ON motions(sitting_id, status);

CREATE TABLE debate_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  motion_id UUID NOT NULL REFERENCES motions(id) ON DELETE RESTRICT,
  speaker_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  status debate_request_status NOT NULL DEFAULT 'pending',
  requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  reviewed_by UUID REFERENCES users(id) ON DELETE RESTRICT,
  reviewed_at TIMESTAMPTZ,
  speaking_started_at TIMESTAMPTZ,
  speaking_ended_at TIMESTAMPTZ,
  allocated_seconds SMALLINT NOT NULL DEFAULT 120 CHECK (allocated_seconds BETWEEN 30 AND 600),
  queue_position INTEGER CHECK (queue_position IS NULL OR queue_position > 0)
);
CREATE INDEX debate_queue_idx ON debate_requests(motion_id, status, queue_position);

CREATE TABLE motion_amendments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  motion_id UUID NOT NULL REFERENCES motions(id) ON DELETE RESTRICT,
  proposed_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  body TEXT NOT NULL CHECK (length(trim(body)) BETWEEN 5 AND 6000),
  status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'accepted', 'rejected', 'withdrawn')),
  reviewed_by UUID REFERENCES users(id) ON DELETE RESTRICT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE votes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  motion_id UUID NOT NULL REFERENCES motions(id) ON DELETE RESTRICT,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  choice vote_choice NOT NULL,
  cast_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (motion_id, user_id)
);
CREATE INDEX votes_motion_choice_idx ON votes(motion_id, choice);

CREATE TABLE concerns (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  submitted_by UUID REFERENCES users(id) ON DELETE SET NULL,
  theme TEXT NOT NULL CHECK (length(trim(theme)) BETWEEN 2 AND 80),
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 5 AND 200),
  description TEXT NOT NULL CHECK (length(trim(description)) BETWEEN 10 AND 8000),
  county TEXT,
  sub_county TEXT,
  ward TEXT,
  status concern_status NOT NULL DEFAULT 'submitted',
  is_public BOOLEAN NOT NULL DEFAULT false,
  moderation_note TEXT,
  assigned_coordinator UUID REFERENCES users(id) ON DELETE RESTRICT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX concerns_review_queue_idx ON concerns(status, created_at DESC);
CREATE INDEX concerns_location_idx ON concerns(county, sub_county, ward);

CREATE TABLE concern_comments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  concern_id UUID NOT NULL REFERENCES concerns(id) ON DELETE CASCADE,
  author_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  body TEXT NOT NULL CHECK (length(trim(body)) BETWEEN 1 AND 3000),
  is_public BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE resolutions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  motion_id UUID NOT NULL UNIQUE REFERENCES motions(id) ON DELETE RESTRICT,
  resolution_number TEXT NOT NULL UNIQUE,
  result TEXT NOT NULL CHECK (result IN ('passed', 'not_passed')),
  status resolution_status NOT NULL DEFAULT 'draft',
  minutes_summary TEXT,
  document_storage_key TEXT,
  approved_by UUID REFERENCES users(id) ON DELETE RESTRICT,
  approved_at TIMESTAMPTZ,
  sent_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE stakeholder_assignments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  resolution_id UUID NOT NULL REFERENCES resolutions(id) ON DELETE RESTRICT,
  stakeholder_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  organisation TEXT NOT NULL,
  granted_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at TIMESTAMPTZ,
  UNIQUE (resolution_id, stakeholder_id)
);

CREATE TABLE stakeholder_updates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  assignment_id UUID NOT NULL REFERENCES stakeholder_assignments(id) ON DELETE RESTRICT,
  stakeholder_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  status stakeholder_update_status NOT NULL,
  comment TEXT NOT NULL CHECK (length(trim(comment)) BETWEEN 3 AND 4000),
  evidence_storage_key TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX stakeholder_updates_assignment_idx ON stakeholder_updates(assignment_id, created_at DESC);

CREATE TABLE audit_logs (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  actor_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  action TEXT NOT NULL CHECK (length(trim(action)) BETWEEN 2 AND 120),
  entity_type TEXT NOT NULL CHECK (length(trim(entity_type)) BETWEEN 2 AND 80),
  entity_id UUID,
  request_id TEXT,
  ip_fingerprint BYTEA,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_entity_idx ON audit_logs(entity_type, entity_id, created_at DESC);
CREATE INDEX audit_logs_actor_idx ON audit_logs(actor_user_id, created_at DESC);

-- Stakeholders receive a narrow, de-identified projection only. Application
-- authorization must additionally enforce assignment ownership on every query.
CREATE VIEW stakeholder_resolution_summary WITH (security_barrier = true) AS
SELECT
  sa.stakeholder_id,
  r.id AS resolution_id,
  r.resolution_number,
  r.result,
  r.status AS resolution_status,
  m.title AS motion_title,
  sa.organisation,
  latest.status AS latest_update_status,
  latest.created_at AS latest_update_at
FROM stakeholder_assignments sa
JOIN resolutions r ON r.id = sa.resolution_id
JOIN motions m ON m.id = r.motion_id
LEFT JOIN LATERAL (
  SELECT su.status, su.created_at
  FROM stakeholder_updates su
  WHERE su.assignment_id = sa.id
  ORDER BY su.created_at DESC
  LIMIT 1
) latest ON true
WHERE sa.revoked_at IS NULL;

-- Public projection deliberately excludes submitter identity, raw descriptions
-- pending moderation, internal notes, and safeguarding referrals.
CREATE VIEW public_concern_summary WITH (security_barrier = true) AS
SELECT id, theme, title, county, sub_county, ward, status, created_at
FROM concerns
WHERE is_public = true
  AND status NOT IN ('referred_to_safeguarding');

COMMIT;
